import {CASES,SAMPLE} from './data.js';
import {normalize,matchEntities,extractText,conflicts,ownershipPaths,escapeHtml as esc} from './core.js';
const $=id=>document.getElementById(id);let MODEL=null,selectedCase='msft',selectedRelation=null,tab='graph',sequence=0;
const state=Object.fromEntries(CASES.map(c=>{const docId=c.id+'-filing';return [c.id,{...c,notes:'',docs:[{id:docId,title:c.title,url:c.url,asof:c.asof,kind:'public',text:'Subsidiaries of '+c.name+'\nAs of '+c.asof+'\nSignificant-subsidiary disclosure; smaller subsidiaries may be omitted.\nName | Jurisdiction\n'+c.rows.map(x=>x.join(' | ')).join('\n'),format:'Normalized transcription of public table facts; open the original for filing context.'}],relations:c.rows.map((x,i)=>({id:c.id+'-'+i,owner:c.name,child:x[0],jurisdiction:x[1],percent:null,kind:'disclosed_subsidiary',docId,quote:x.join(' | '),status:'pending'}))}]}));
const current=()=>state[selectedCase];
const say=message=>{const t=$('toast');t.textContent=message;t.style.display='block';setTimeout(()=>t.style.display='none',4500);};
const label=r=>r.kind==='explicit_ownership'?r.percent+'% explicitly stated':'Listed subsidiary · hierarchy unspecified';
const visibleRelations=()=>current().relations;
function switchCase(id){if(!state[id])throw new Error('Unknown case');selectedCase=id;selectedRelation=current().relations[0]?.id||null;$('query').value='';$('matches').replaceChildren();tab='graph';render();}
function setTab(name){tab=name;for(const n of ['graph','documents','review'])$(n+'View').hidden=n!==name;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===name));}
function render(){const c=current();if(!c.relations.some(r=>r.id===selectedRelation))selectedRelation=c.relations[0]?.id||null;
 $('cases').innerHTML=Object.values(state).map(x=>`<button class="case-item ${x.id===c.id?'active':''}" data-case="${esc(x.id)}"><b>${esc(x.name)}</b><small>${esc(x.caseId)} · ${x.kind==='public'?'Public filing':'Fictional example'}</small></button>`).join('');
 $('caseId').textContent=c.caseId;$('caseName').textContent=c.name;$('caseSub').textContent=(c.kind==='public'?'Public filing snapshot':'Fictional ownership example')+' · as of '+c.asof+' · Case changes last for this tab session';
 const cs=conflicts(c.relations);$('metrics').innerHTML=[[c.relations.filter(r=>r.status!=='rejected').length,'Candidate relationships'],[c.docs.length,'Source documents'],['Not established','Ultimate human owners'],[cs.length?cs.length+' conflicts':'Review needed',cs.length?'Competing ownership claims':'Ownership evidence incomplete']].map(([n,t],i)=>`<div class="metric ${i>1?'warn':''}"><strong style="${String(n).length>10?'font-size:18px':''}">${esc(n)}</strong><small>${esc(t)}</small></div>`).join('');
 $('graphNote').textContent=c.kind==='public'?'Connections mean “listed in this registrant’s disclosure”, not necessarily immediate ownership. Click a relationship to inspect its source.':'Fictional, explicit ownership statements. Click a relationship to inspect its evidence and any indirect path.';
 $('graph').innerHTML=`<div class="root-node">${esc(c.name)}<small>${c.kind==='public'?'Filing registrant · not a verified ultimate owner':'Fictional parent company'}</small></div><div class="node-list">${c.relations.map(r=>`<button class="entity-node ${r.id===selectedRelation?'selected':''}" data-relation="${esc(r.id)}" style="${r.status==='rejected'?'opacity:.5':''}">${esc(r.child)}<small>${esc(r.jurisdiction)}</small><div class="relation">${esc(label(r))}</div>${normalize(r.owner)!==normalize(c.name)?`<small>From: ${esc(r.owner)}</small>`:''}<small>${r.status==='accepted'?'✓ Evidence reviewed':r.status==='rejected'?'Excluded by analyst':'Awaiting analyst review'}</small></button>`).join('')}</div>${!c.relations.length?'<p class="empty">No supported relationships found. Add a document with an explicit ownership statement or a subsidiary table.</p>':''}`;
 renderEvidence();renderDocuments();renderReview();setTab(tab);
}
function renderEvidence(){const c=current(),r=c.relations.find(x=>x.id===selectedRelation);if(!r){$('evidence').innerHTML='<h2>Select a relationship</h2><p>Each candidate remains linked to the document that supplied it.</p>';return;}const doc=c.docs.find(d=>d.id===r.docId);const disputed=conflicts(c.relations).some(rs=>rs.some(x=>x.id===r.id));const paths=ownershipPaths(c.relations,c.name,r.child).filter(p=>p.path.length>1);
 $('evidence').innerHTML=`<span class="badge ${doc.kind==='public'?'':'amber'}">${doc.kind==='public'?'PUBLIC FILING':doc.kind==='synthetic'?'FICTIONAL EXAMPLE':'UNVERIFIED INPUT'}</span><h2>${esc(r.child)}</h2><p>${esc(r.owner)} → ${esc(r.child)}</p>${disputed?'<div class="conflict">Conflicting percentages in the evidence. No single percentage is resolved automatically.</div>':''}<blockquote>${esc(r.quote)}</blockquote><dl><dt>Relationship supported</dt><dd>${esc(label(r))}</dd><dt>Source</dt><dd>${esc(doc.title)}</dd><dt>${doc.kind==='uploaded'?'Claimed as-of date (unverified)':'Evidence date'}</dt><dd>${esc(doc.asof||'Not established')}</dd><dt>Source location</dt><dd>${r.page?'PDF page '+r.page:r.line?'Text line '+r.line:'Exhibit table row (normalized transcription)'}</dd><dt>Not established</dt><dd>${r.percent===null?'Immediate parent, percentage, full chain and human owners.':'Ultimate human owners, completeness and independent authenticity.'}</dd></dl>${paths.map(p=>`<div class="conflict" style="border-color:#849c65;background:#f2f6e9">${p.percent.toFixed(2)}% through this disclosed path: ${p.path.map(x=>esc(x.owner)).join(' → ')} → ${esc(r.child)}. Arithmetic only; paths are not summed or treated as verified beneficial ownership.</div>`).join('')}${doc.url?`<a href="${esc(doc.url)}" target="_blank" rel="noopener noreferrer">Open original SEC filing ↗</a>`:''}<button class="quiet" id="viewDocBtn">View case source text →</button><div class="review-buttons"><button data-review="accepted">Mark evidence reviewed</button><button data-review="rejected" class="outline">Exclude relationship</button><button data-review="pending" class="quiet">Reset</button></div><p style="font-size:10px;margin-top:10px">Review records your assessment of the cited relationship, not verification of the business or its owners.</p>`;
}
function renderDocuments(){const c=current();$('documentsView').innerHTML=`<div class="panel-header"><div><h2>Source documents</h2><p>Click-through provenance for every extracted candidate.</p></div><button class="outline" data-add-doc>Add document</button></div>`+c.docs.map(d=>`<article class="doc-card"><span class="badge ${d.kind==='public'?'':'amber'}">${d.kind==='public'?'Public record':d.kind==='synthetic'?'Fictional example':'Analyst supplied'}</span><h3>${esc(d.title)}</h3><div class="meta">As of ${esc(d.asof||'unknown')} · ${esc(d.format||'Pasted text')} · ${d.pages||1} ${d.pages?'PDF pages':'text section'}</div>${d.url?`<a href="${esc(d.url)}" target="_blank" rel="noopener">Original source ↗</a>`:''}<pre>${esc(d.text)}</pre></article>`).join('');}
function gaps(){const c=current(),rs=c.relations.filter(r=>r.status!=='rejected'),cs=conflicts(rs);let out=[{title:'Ultimate human owners are not established',text:'The available evidence does not complete a chain to independently verified natural persons. Do not mark this as a completed UBO check.'}];if(rs.some(r=>r.percent===null))out.push({title:'Subsidiary disclosure is not a direct ownership map',text:'The public exhibit does not state immediate-parent links or percentages. Obtain additional evidence before calculating ownership.'});if(cs.length)out.push({title:cs.length+' conflicting ownership pair(s)',text:'Different percentages are stated for the same relationship. Compare dates and document authority; the app does not choose a winner.'});if(c.docs.some(d=>d.kind==='uploaded'))out.push({title:'Analyst-supplied documents need source validation',text:'Uploaded content is evidence to review, not an authoritative record merely because it was parsed.'});out.push({title:'Snapshot coverage and recency need review',text:'Public examples are dated filings, not live registry checks. Significant-subsidiary exhibits may omit smaller entities.'});return out;}
function renderReview(){const c=current();$('reviewView').innerHTML=`<div class="panel-header"><div><h2>What the analyst still needs</h2><p>Open questions are preserved in the exported brief.</p></div><span class="badge amber">Investigation incomplete</span></div>`+gaps().map((g,i)=>`<div class="gap-card"><span class="number">${i+1}</span><div><h3 style="margin-top:0">${esc(g.title)}</h3><p>${esc(g.text)}</p></div></div>`).join('')+`<div class="review-notes"><label for="notes">Analyst notes · saved in this tab until export</label><textarea id="notes" rows="5" placeholder="What evidence would you request next?">${esc(c.notes)}</textarea><p style="font-size:11px">Export the case before closing this tab. No data is shared with other visitors.</p></div>`;}
async function search(){const q=$('query').value.trim();if(!q){$('matches').textContent='Enter a business name to compare with this case’s evidence.';return;}if(!MODEL){$('matches').textContent='The matching model is unavailable. Reload the page to try again; source evidence remains usable.';return;}const rs=current().relations;const result=matchEntities(q,[current().name,...rs.flatMap(r=>[r.owner,r.child])],MODEL);$('matches').innerHTML=result.map(x=>`<div class="match"><div><b>${esc(x.name)}</b><small>${x.score>=MODEL.threshold?'Candidate above model threshold · verify against source':'Weak match · do not resolve automatically'} · score ${x.score.toFixed(3)}</small></div><button class="outline" data-match="${esc(x.name)}">Inspect</button></div>`).join('')+'<p style="font-size:10px">Learned lexical matching, not a verified identity or calibrated confidence. The model does not merge entities automatically.</p>';}
let pendingPages=null;
function openUpload(){$('uploadStatus').textContent='';$('uploadDialog').showModal();}
function addDocument(text,title,pages=null){if(!text.trim())throw new Error('Add document text first.');if(text.length>500000)throw new Error('Text limit is 500,000 characters. Use a smaller excerpt.');const c=current(),id='upload-'+(++sequence),date=text.match(/\bas of\s+(20\d{2}-\d{2}-\d{2})\b/i)?.[1]||null;const extracted=extractText(text,c.name,id);c.docs.push({id,title:title.slice(0,180)||'Analyst-supplied document',text,kind:'uploaded',asof:date,format:pages?'Text extracted from PDF':'Analyst-supplied text',pages:pages?.length});
 for(const r of extracted.relations){r.id=id+'-'+c.relations.length;if(pages){let cursor=0;for(let i=0;i<pages.length;i++){if(r.offset>=cursor&&r.offset<cursor+pages[i].length+1){r.page=i+1;break;}cursor+=pages[i].length+1;}}c.relations.push(r);}
 selectedRelation=extracted.relations[0]?.id||selectedRelation;render();return {relationships:extracted.relations.length,warnings:extracted.warnings};}
async function handleFile(file){if(!file)return;if(file.size>10*1024*1024){$('uploadStatus').textContent='File limit is 10 MB. Please use a smaller document.';return;}pendingPages=null;$('docText').value='';$('analyzeBtn').disabled=true;$('uploadStatus').textContent='Reading the document in your browser…';$('docTitle').value=file.name;
 try{let text;if(/\.pdf$/i.test(file.name)){const pdfjs=await import('./vendor/pdf.min.mjs');pdfjs.GlobalWorkerOptions.workerSrc='./vendor/pdf.worker.min.mjs';const loadingTask=pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer()),isEvalSupported:false});const pdf=await loadingTask.promise;if(pdf.numPages>60)throw new Error('Please use a PDF with 60 pages or fewer.');pendingPages=[];for(let i=1;i<=pdf.numPages;i++){const page=await pdf.getPage(i);const content=await page.getTextContent();pendingPages.push(content.items.map(x=>x.str+(x.hasEOL?'\n':' ')).join(''));}text=pendingPages.join('\n');await loadingTask.destroy();if(text.trim().length<20)throw new Error('No usable text found. This may be a scanned PDF; OCR it first or paste an excerpt.');}else{if(!/\.(txt|html|htm)$/i.test(file.name))throw new Error('Choose a PDF, HTML or TXT file.');text=await file.text();if(/\.html?$/i.test(file.name)){const dom=new DOMParser().parseFromString(text,'text/html');dom.querySelectorAll('script,style,iframe,object').forEach(n=>n.remove());let rows=[...dom.querySelectorAll('tr')].map(tr=>[...tr.querySelectorAll('td,th')].map(td=>td.textContent.trim().replace(/\s+/g,' ')).filter(Boolean).join(' | '));text=dom.body.textContent.replace(/\s+/g,' ').slice(0,3000)+'\n'+rows.join('\n');}}
 if(text.length>500000)throw new Error('Extracted text exceeds 500,000 characters. Use a smaller excerpt.');$('docText').value=text;$('uploadStatus').textContent='Ready to analyze. Review the text before extracting relationships.';}catch(e){$('uploadStatus').textContent=e.message;pendingPages=null;}finally{$('analyzeBtn').disabled=false;}}
function sample(){if(!state.example)state.example={id:'example',caseId:'DEMO-1044',name:'Northstar Commerce PLC',kind:'synthetic',asof:'2026-01-15',notes:'',docs:[],relations:[]};switchCase('example');if(!current().docs.length){addDocument(SAMPLE,'Fictional ownership statement');current().docs[0].kind='synthetic';render();}say('Fictional example loaded. Select Willow Services to inspect the 48% indirect path.');}
function exportBrief(){const c=current(),now=new Date().toISOString();const html=`<!doctype html><meta charset="utf-8"><title>${esc(c.name)} · Evidence brief</title><style>body{font:15px/1.6 system-ui;max-width:950px;margin:40px auto;padding:20px;color:#213b35}table{border-collapse:collapse;width:100%}td,th{border:1px solid #ddd;padding:9px;text-align:left;font-size:12px}blockquote{border-left:3px solid #748e72;padding-left:15px}small{color:#627267}</style><h1>${esc(c.name)}</h1><p>Evidence investigation brief · ${esc(c.caseId)} · Exported ${esc(now)}</p><p><b>Incomplete investigation. No ultimate human owner established.</b></p><p>${c.kind==='public'?'Real public-company evidence; fictional onboarding case.':'Fictional example, not a real company investigation.'} No affiliation with Trulioo. This brief is not a compliance determination.</p><h2>Relationships</h2><table><tr><th>From</th><th>To</th><th>Evidence</th><th>Review</th><th>Source</th></tr>${c.relations.map(r=>`<tr><td>${esc(r.owner)}</td><td>${esc(r.child)}</td><td>${esc(label(r))}</td><td>${esc(r.status)}</td><td>${esc(c.docs.find(d=>d.id===r.docId)?.title)}</td></tr>`).join('')}</table><h2>Evidence excerpts</h2>${c.relations.map(r=>`<h3>${esc(r.child)}</h3><blockquote>${esc(r.quote)}</blockquote>`).join('')}<h2>Open questions</h2><ul>${gaps().map(g=>`<li><b>${esc(g.title)}</b>: ${esc(g.text)}</li>`).join('')}</ul><h2>Analyst notes</h2><p style="white-space:pre-wrap">${esc(c.notes||'No notes added.')}</p><h2>Sources</h2>${c.docs.map(d=>`<p><b>${esc(d.title)}</b> · ${esc(d.asof||'Date unknown')} · ${esc(d.kind)}${d.url?`<br><a href="${esc(d.url)}">${esc(d.url)}</a>`:''}</p>`).join('')}<small>ML assists name ranking only. Extraction uses explicit supported patterns. Source context and document authenticity require analyst review.</small>`;const url=URL.createObjectURL(new Blob([html],{type:'text/html'}));const a=document.createElement('a');a.href=url;a.download=c.id+'-evidence-brief.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);say('Brief exported with evidence, review decisions and open questions.');}
$('cases').onclick=e=>{const b=e.target.closest('[data-case]');if(b)switchCase(b.dataset.case);};$('graph').onclick=e=>{const b=e.target.closest('[data-relation]');if(b){selectedRelation=b.dataset.relation;render();}};document.querySelector('.tabs').onclick=e=>{const b=e.target.closest('[data-tab]');if(b)setTab(b.dataset.tab);};$('evidence').onclick=e=>{const b=e.target.closest('[data-review]');if(b){current().relations.find(r=>r.id===selectedRelation).status=b.dataset.review;render();say('Analyst review updated for this tab session.');}if(e.target.id==='viewDocBtn')setTab('documents');};$('documentsView').onclick=e=>{if(e.target.closest('[data-add-doc]'))openUpload();};$('reviewView').oninput=e=>{if(e.target.id==='notes')current().notes=e.target.value;};$('matches').onclick=e=>{const b=e.target.closest('[data-match]');if(b){selectedRelation=current().relations.find(r=>r.child===b.dataset.match||r.owner===b.dataset.match)?.id||null;tab='graph';render();$('graphView').scrollIntoView({behavior:'smooth',block:'start'});}};
$('searchBtn').onclick=search;$('query').onkeydown=e=>{if(e.key==='Enter')search();};$('uploadBtn').onclick=openUpload;$('pickFile').onclick=()=>$('fileInput').click();$('fileInput').onchange=e=>handleFile(e.target.files[0]);$('docText').oninput=()=>pendingPages=null;$('analyzeBtn').onclick=()=>{try{const r=addDocument($('docText').value,$('docTitle').value,pendingPages);$('uploadDialog').close();$('docText').value='';pendingPages=null;say(`${r.relationships} candidate relationships extracted. ${r.warnings.join(' ')||(!r.relationships?'Document retained for manual review.':'Review each against its source.')}`);}catch(e){$('uploadStatus').textContent=e.message;}};$('exampleBtn').onclick=sample;$('exportBtn').onclick=exportBrief;$('aboutBtn').onclick=()=>$('aboutDialog').showModal();
switchCase('msft');fetch('./model.json').then(r=>{if(!r.ok)throw new Error('Model missing');return r.json();}).then(m=>MODEL=m).catch(()=>say('Name model could not load. Source review is still available.'));
if(document.modelContext?.registerTool){for(const tool of [{name:'read_evidence_case',description:'Read current case relationships and unresolved questions. No state changes.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({name:current().name,relationships:current().relations.map(r=>({owner:r.owner,child:r.child,percent:r.percent,status:r.status})),gaps:gaps()})},{name:'select_evidence_case',description:'Navigate to a bundled investigation case; does not verify it.',inputSchema:{type:'object',properties:{caseId:{type:'string',enum:['msft','alphabet']}},required:['caseId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!['msft','alphabet'].includes(input.caseId))throw new Error('Invalid caseId');switchCase(input.caseId);return {selected:input.caseId};}}]){try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{});}catch{}}}
